const item = $input.first().json;
let data = item;
if (item.candidates && item.candidates[0] && item.candidates[0].content
  && item.candidates[0].content.parts && item.candidates[0].content.parts[0]
  && item.candidates[0].content.parts[0].text) {
  data = item.candidates[0].content.parts[0].text;
} else if (item.message && item.message.content) {
  data = item.message.content;
} else if (item.choices && item.choices[0] && item.choices[0].message && item.choices[0].message.content) {
  data = item.choices[0].message.content;
}
if (typeof data === 'string') {
  data = data.replace(/^```(json)?\s*/i, '').replace(/\s*```$/i, '').trim();
  data = JSON.parse(data);
}
const required = ['vendor', 'invoiceNumber', 'totalAmount'];
const missing = required.filter(k => data[k] === null || data[k] === undefined || data[k] === '');
if (missing.length) {
  throw new Error('Missing required fields: ' + missing.join(', '));
}
const lineItems = Array.isArray(data.lineItems) ? data.lineItems : [];
const calcSubtotal = lineItems.reduce((s, li) => s + (Number(li.amount) || 0), 0);
const subtotal = Number(data.subtotal);
const taxAmount = Number(data.taxAmount) || 0;
const totalAmount = Number(data.totalAmount) || 0;
const base = isNaN(subtotal) ? calcSubtotal : subtotal;
const calcTotal = base + taxAmount;
const mathOk = Math.abs(calcTotal - totalAmount) < 0.05;
return [{
  json: {
    vendor: String(data.vendor || '').trim(),
    billTo: String(data.billTo || '').trim(),
    invoiceNumber: String(data.invoiceNumber || '').trim(),
    invoiceDate: data.invoiceDate || null,
    dueDate: data.dueDate || null,
    poNumber: data.poNumber || null,
    paymentTerms: data.paymentTerms || null,
    currency: (data.currency || 'USD').toUpperCase(),
    subtotal: isNaN(subtotal) ? calcSubtotal : subtotal,
    taxRate: Number(data.taxRate) || null,
    taxAmount: taxAmount,
    totalAmount: totalAmount,
    lineItems: lineItems,
    mathCheck: mathOk ? 'OK' : 'MISMATCH',
    status: 'Pending',
    extractedAt: new Date().toISOString()
  }
}];
